from __future__ import annotations

import base64
import hashlib
import py_compile
import shutil
import sys
from datetime import datetime
from pathlib import Path

try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:
    pass

TITLE = "SÁP NHẬP TOÀN CẤP - CÀI ĐẶT CHỨC NĂNG THỰC HIỆN MỘT LẦN CHUNG CHO TOÀN CẤP"
EMBEDDED_FILES = {'app/services/school_merger_level_batch_service.py': '', 'app/routers/school_merger_level_batch.py': '', 'app/templates/data_tools/school_merger_level_batch.html': '', 'app/templates/data_tools/school_merger_level_batch_result.html': ''}


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def find_root() -> Path:
    starts = [Path.cwd(), Path(__file__).resolve().parent, Path(__file__).resolve().parent.parent]
    for p in starts:
        if (p / "app" / "main.py").exists() and (p / "data" / "phocap.db").exists():
            return p.resolve()
    raise RuntimeError(r"Không xác định được dự án C:\PhoCap. Hãy chép bộ cài vào C:\PhoCap rồi chạy lại.")


def patch_main(text: str) -> str:
    import_line = "from app.routers.school_merger_level_batch import router as school_merger_level_batch_router"
    include_line = "app.include_router(school_merger_level_batch_router)"
    if import_line not in text:
        anchors = [
            "from app.routers.school_merger_future import router as school_merger_future_router",
            "from app.routers.school_merger import router as school_merger_router",
        ]
        for anchor in anchors:
            if anchor in text:
                text = text.replace(anchor, anchor + "\n# === SCHOOL_MERGER_LEVEL_BATCH_IMPORT ===\n" + import_line, 1)
                break
        else:
            raise RuntimeError("Không tìm thấy vị trí an toàn để thêm router sáp nhập toàn cấp trong app/main.py")
    if include_line not in text:
        anchors = [
            "app.include_router(school_merger_future_router)",
            "app.include_router(school_merger_router)",
        ]
        for anchor in anchors:
            if anchor in text:
                text = text.replace(anchor, anchor + "\n# === SCHOOL_MERGER_LEVEL_BATCH_INCLUDE ===\n" + include_line, 1)
                break
        else:
            raise RuntimeError("Không tìm thấy vị trí an toàn để include router sáp nhập toàn cấp trong app/main.py")
    return text


def patch_dashboard(text: str) -> str:
    if "/cong-cu-du-lieu/sap-nhap-truong/toan-cap" in text:
        return text
    button = '<a class="btn primary" href="/cong-cu-du-lieu/sap-nhap-truong/toan-cap?school_year_id={{ selected_school_year_id or \'\' }}&level_code={{ selected_level_code }}">SÁP NHẬP TOÀN CẤP</a>'
    # Ưu tiên chèn ngay trước nút SÁP NHẬP PHÁT SINH.
    marker = '<a class="btn primary" href="/cong-cu-du-lieu/sap-nhap-truong/phat-sinh'
    pos = text.find(marker)
    if pos >= 0:
        return text[:pos] + button + text[pos:]
    # Nếu giao diện đã đổi class, chèn sau nút Phương án chính thức.
    marker = 'href="/cong-cu-du-lieu/sap-nhap-truong/phuong-an"'
    pos = text.find(marker)
    if pos >= 0:
        start = text.rfind("<a", 0, pos)
        end = text.find("</a>", pos)
        if start >= 0 and end >= 0:
            end += len("</a>")
            return text[:end] + button + text[end:]
    # Fallback: sau div actions đầu tiên.
    marker = '<div class="actions">'
    pos = text.find(marker)
    if pos >= 0:
        pos += len(marker)
        return text[:pos] + button + text[pos:]
    raise RuntimeError("Không tìm thấy vị trí an toàn để thêm nút SÁP NHẬP TOÀN CẤP trong bảng điều khiển.")


def main() -> int:
    print("=" * 112)
    print(TITLE)
    print("Nguyên tắc: chỉ cài chức năng. KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
    print("=" * 112)

    root = find_root()
    db = root / "data" / "phocap.db"
    db_hash_before = sha256_file(db)

    required = [
        root / "app" / "main.py",
        root / "app" / "services" / "school_merger_service.py",
        root / "app" / "services" / "school_merger_execution_service.py",
        root / "app" / "services" / "school_merger_preview_service.py",
        root / "app" / "services" / "school_merger_source_audit_service.py",
        root / "app" / "services" / "school_merger_official_registry.py",
        root / "app" / "templates" / "data_tools" / "school_merger_dashboard_v45.html",
    ]
    missing = [str(p.relative_to(root)) for p in required if not p.exists()]
    if missing:
        raise RuntimeError("Thiếu tệp nền bắt buộc: " + ", ".join(missing))

    checks = {
        root / "app" / "services" / "school_merger_execution_service.py": [
            "annotate_official_plan_execution_status",
            "school_merger_official_executions",
        ],
        root / "app" / "services" / "school_merger_preview_service.py": ["build_official_plan_impact_preview"],
        root / "app" / "services" / "school_merger_source_audit_service.py": ["audit_official_plans"],
        root / "app" / "services" / "school_merger_official_registry.py": ["list_official_registry_plans"],
    }
    for path, markers in checks.items():
        src = path.read_text(encoding="utf-8", errors="replace")
        for marker in markers:
            if marker not in src:
                raise RuntimeError(f"Tệp {path.relative_to(root)} không có marker bắt buộc: {marker}")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = root / "backups" / f"backup_truoc_cai_sap_nhap_toan_cap_{stamp}"
    backup.mkdir(parents=True, exist_ok=False)

    changed_existing = [
        root / "app" / "main.py",
        root / "app" / "templates" / "data_tools" / "school_merger_dashboard_v45.html",
    ]
    created_paths: list[Path] = []
    for p in changed_existing:
        dst = backup / p.relative_to(root)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dst)

    try:
        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            if p.exists():
                dst = backup / p.relative_to(root)
                dst.parent.mkdir(parents=True, exist_ok=True)
                if not dst.exists():
                    shutil.copy2(p, dst)
            else:
                created_paths.append(p)
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(base64.b64decode(b64))

        main_path = root / "app" / "main.py"
        main_path.write_text(patch_main(main_path.read_text(encoding="utf-8")), encoding="utf-8")

        dash_path = root / "app" / "templates" / "data_tools" / "school_merger_dashboard_v45.html"
        dash_path.write_text(patch_dashboard(dash_path.read_text(encoding="utf-8")), encoding="utf-8")

        for rel in [
            "app/main.py",
            "app/routers/school_merger_level_batch.py",
            "app/services/school_merger_level_batch_service.py",
        ]:
            py_compile.compile(str(root / rel), doraise=True)

        try:
            from jinja2 import Environment
            env = Environment()
            for rel in [
                "app/templates/data_tools/school_merger_level_batch.html",
                "app/templates/data_tools/school_merger_level_batch_result.html",
            ]:
                env.parse((root / rel).read_text(encoding="utf-8"))
        except ImportError:
            pass

        main_src = (root / "app" / "main.py").read_text(encoding="utf-8")
        dash_src = dash_path.read_text(encoding="utf-8")
        service_src = (root / "app" / "services" / "school_merger_level_batch_service.py").read_text(encoding="utf-8")
        must = [
            ("main import", "school_merger_level_batch_router" in main_src),
            ("main include", "app.include_router(school_merger_level_batch_router)" in main_src),
            ("dashboard button", "/sap-nhap-truong/toan-cap" in dash_src),
            ("single transaction", "BEGIN IMMEDIATE" in service_src),
            ("rollback", "con.rollback()" in service_src),
            ("backup", "backup_truoc_sap_nhap_toan_cap" in service_src),
            ("integrity", "PRAGMA integrity_check" in service_src),
            ("fk", "PRAGMA foreign_key_check" in service_src),
            ("batch log", "school_merger_level_batches" in service_src),
        ]
        bad = [name for name, ok in must if not ok]
        if bad:
            raise RuntimeError("Smoke audit chưa đạt: " + ", ".join(bad))

        db_hash_after = sha256_file(db)
        if db_hash_before != db_hash_after:
            raise RuntimeError("Database thay đổi trong lúc cài. Bộ cài đã dừng an toàn.")

    except Exception:
        for p in changed_existing + [root / rel for rel in EMBEDDED_FILES]:
            src = backup / p.relative_to(root)
            if src.exists():
                p.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, p)
        for p in created_paths:
            src = backup / p.relative_to(root)
            if p.exists() and not src.exists():
                try:
                    p.unlink()
                except Exception:
                    pass
        raise

    print()
    print("=" * 112)
    print("CÀI ĐẶT THÀNH CÔNG - SÁP NHẬP TOÀN CẤP")
    print("Database: KHÔNG THAY ĐỔI")
    print("Đã thêm: KIỂM TRA SẴN SÀNG TOÀN CẤP -> SÁP NHẬP TOÀN CẤP")
    print("Điều kiện mở nút: CHẶN = 0; GIỮ NGUYÊN/ĐÃ THỰC HIỆN được bỏ qua; không chạy lại.")
    print("Khi thực hiện thật: 1 backup chung + 1 transaction chung + hậu kiểm integrity/FK trước COMMIT.")
    print("Nếu một phương án lỗi trước COMMIT: rollback TOÀN CẤP.")
    print(f"Backup mã nguồn trước cài: {backup}")
    print("Bộ cài này KHÔNG thực hiện sáp nhập.")
    print("=" * 112)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print("=" * 112)
        print("DỪNG AN TOÀN - CÀI CHỨC NĂNG SÁP NHẬP TOÀN CẤP")
        print("Mã nguồn đã được khôi phục nếu đã chạm file.")
        print("Lỗi:", exc)
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 112)
        raise SystemExit(1)
